# ------------- QUESTION CLASS --------------
class Dimension(models.Model):
    idD =       models.SmallAutoField(primary_key=True)
    orden =     models.PositiveSmallIntegerField() 
    dimension = models.CharField(max_length=30)

    class Meta:
        indexes = [models.Index(fields=['dimension'])]
        ordering = ['orden']

    def __str__(self):
        return str('ID ' + self.id + ' Dimension ' + self.dimension)

class InterestArea(models.Model):
    idA =       models.SmallAutoField(primary_key=True)
    orden =     models.CharField()
    int_area =  models.CharField(max_length=30)
    idD = models.ForeignKey(Dimension, on_delete=models.CASCADE, null=True)

    class Meta:
        indexes = [models.Index(fields=['int_area'])]
        ordering = ['orden']

    def __str__(self):
        return str('ID ' + self.id + ' Orden '+ self.orden + ' Área de Interés ' + self.int_area + ' Dimension ' + self.dimension)
      
class CoreContent(models.Model):
    idC =       models.SmallAutoField(primary_key=True)
    core_cont = models.CharField(max_length=30)
    idA =       models.ForeignKey(InterestArea, on_delete=models.CASCADE, null=True)

    class Meta:
        ordering = ['core_cont']
    
    def __str__(self):
        return str('ID ' + self.id + ' Contenido Nuclear ' + self.core_cont + ' Área de interés ' + self.int_area)

class Question(models.Model): 
    class QuestionManager(models.Manager):
        def get_queryset(self):
            return super().get_queryset().values().annotate()
        
    idP =               models.BigAutoField(primary_key=True)
    numero =            models.PositiveIntegerField(default=1)
    statement =         models.CharField(max_length= 50, unique=True)  
    time =              models.TimeField()
    difficult_level =   models.PositiveSmallIntegerField()
    version =           models.PositiveIntegerField(default=0)
    date =              models.DateTimeField(auto_now=True)
    idD =               models.ForeignKey(Dimension, on_delete=models.SET_NULL, null=True)

    class Meta:
        indexes = [models.Index(fields=['statement', 'numero', 'version'])]
        
    def __str__(self):
        return str(f'ID: {self.idP}, Número: {self.numero}, Version: {self.version}, Enunciado: {self.statement}')

# Class that represents the solution at all the options, relathinship many to one with question
class Option(models.Model):
    idO =               models.AutoField(default=1, primary_key=True)
    option =            models.CharField(max_length=25)
    question =          models.ManyToManyField(Question, through='OptionQuestion', related_name='question_values')

    class Meta:
        indexes = [models.Index(fields=['option'])]    

    def __str__(self):
        return str('ID ' + self.id + ' Opción ' + self.option)

class OptionQuestion(models.Model): 
    
    # get only the solutions for each question id of all options 
    class OptionQuestionManager(models.Manager):
        def get_queryset(self):
            return super().get_queryset().values('idP').annotate('idP').exclude(Q(motive__isnull=True)|Q(motive='')|Q(motive=' ')).values('idP', 'idO', 'motive')
        
    idP =       models.ForeignKey(Question, on_delete=models.CASCADE, related_name='option_value_to_question')
    idO =       models.ForeignKey(Option, on_delete=models.CASCADE, related_name='option_value') # this id of the value
    motive =    models.TextField(max_length=250, null=True)
    pk =        models.CompositePrimaryKey('idP', 'idO')

    objects =   models.Manager() #default
    solutions=  OptionQuestionManager() 
        
    def __str__(self):
        return str('Pregunta ' + self.idP + ' Valor ' + self.idO)
    
# ------------- QUIZ CLASS --------------------
class Quiz(models.Model):
    idQ =       models.AutoField(primary_key=True)
    file =      models.CharField(max_length=20)
    fechaC =    models.DateTimeField(auto_now_add=True)
    fechaA =    models.DateTimeField(auto_now=True)
    question =  models.ManyToManyField('Question', through='AppearanceQuiz', related_name='question_in_each_quiz')

    def __str__(self):
       return str('ID: '+  self.idQ + ' fecha creación: ' + self.fechaC + ' fecha actualización:' + self.fechaA)
    
class AppearanceQuiz(models.Model):
    quiz =      models.ForeignKey(Quiz, on_delete=models.CASCADE)
    question =  models.ForeignKey(Question, on_delete=models.CASCADE)
    pk =        models.CompositePrimaryKey('question', 'quiz')

#----------- INTERVIEWER CLASS(is MyUser) ---------
# AbstractUser to adapt default User Django Class
class MyUser(AbstractBaseUser, PermissionsMixin):
    
    class MyUserManager(BaseUserManager):
                
        def create_user(self, username, password, is_staff, **extra_fields):
            user = self.model(username, password, is_staff, **extra_fields)
                            
            if is_staff == True:
                user = self.model(username=username, is_staff=is_staff, **extra_fields)
                user.set_password(password)
            
            user.save()
            return user
        
        
        def create_superuser(self, username, password, **extra_fields):
            user = self.model(username=username, is_superuser=True, **extra_fields)
            user.set_password(password)
            
            user.save()
            return user        
            
    id =            models.UUIDField(primary_key=True, default=uuid.uuid4, editable=False, auto_created=True)
    username=       models.CharField(max_length=256, unique=True, null=True)
    password =      models.CharField(max_length=256, editable=False, null=True) 
    is_staff =      models.BooleanField(default=False)
    is_superuser =  models.BooleanField(default=False)

    objects =       MyUserManager()
    
    USERNAME_FIELD = 'username'

    def save(self, force_insert = ..., force_update = ..., using = ..., update_fields = ...):
        
        if self.is_staff is True:
            group = create_group('interviewer')
            self.groups().add(group)
            
        return super().save(force_insert, force_update, using, update_fields)

    def __str__(self):
       return str('ID: '+ + self.id + ' usuario: ' + self.username + ' password:' + self.password)  
    
