class Satisfation(models.Model):

    RANKING_INDIVIUAL = {
        'Nunca' :                       0,
        'De vez en cuando':             1,
        'Menos de la mitad del tiempo': 2,
        'Más de la mitad del tiempo':   3,
        'La mayor parte del tiempo':    4,
        'Todo el tiempo':               5
    }     

    idSas =     models.AutoField(primary_key=True)
    questionS =  models.CharField(max_length=200)
    value =     models.PositiveSmallIntegerField(choices=RANKING_INDIVIUAL)
    
class  AcademicLevel(models.Model):
    class AcademicLevelTypes(models.TextChoices):
        Grado = 'Grado'
        Máster = 'Máster'
        Doctorado = 'Doctorado'

    academic_lvl =  models.CharField(max_length=10, choices=AcademicLevelTypes) #academic_lvl
    description =   models.CharField(max_length=50, null=True)
    # null True permits set null in a database field
    year =          models.PositiveSmallIntegerField(null=True)
           
class Respondant(models.Model):

    class Sex(models.TextChoices):
        F = 'Femenino'
        M = 'Masculino'  

    respondant =        models.OneToOneField(MyUser, on_delete=models.CASCADE)
    age =               models.PositiveSmallIntegerField()
    sex =               models.CharField(choices=Sex)
    nationality =       models.CharField(max_length=15)
    city =              models.CharField(max_length=25)
    region =            models.CharField(max_length=25)
    level_PBE =         models.PositiveSmallIntegerField()
    PBE_knownledge =    models.BooleanField(default=False)
    PBE_training =      models.CharField(max_length=30)
    speciality =        models.CharField(max_length=20, null=True)
    academic_level =    models.ForeignKey(AcademicLevel, on_delete=models.CASCADE, null=True)
    
    
    # if i change the name to reply or answer don't works but Respuesta sí.
    question =    models.ManyToManyField(Question, through='Respuesta', related_name='respondant_answer_to_question')
    profarea =    models.ManyToManyField(ProfesionalArea, through='SatisfationGrade', related_name='profesional_area_user')
    satisfation = models.ManyToManyField(Satisfation, through='SatisfationRes', related_name='satisfation_per_user')
    
    def save(self, force_insert = ..., force_update = ..., using = ..., update_fields = ...):
        group = create_group('respondant')
        self.respondant.groups().add(group)
        return super().save(force_insert, force_update, using, update_fields)
    
    def __str__(self):
       return str('ID: '+ self.respondant.id+ ' Edad: '+self.age+ ' Sexo: '+ self.sex + ' Nacionalidad: '+ self.nationality + ' Ciudad: '+ self.city + 
                  ' Región: ' + self.region +  ' Título: '+ self.title + ' Año de titulación: '+ self.year_title + ' Area profesional/estudio: '+ 
                  self.areaprof.values_list(flat=True)+ ' Nivel de PBE: ' + self.level_PBE +' Conocimiento en PBE '+ self.PBE_knownledge + ' Especialidad: '+ self.speciality)
    
class SatisfationRes(models.Model):
    idS =   models.ForeignKey(Satisfation, on_delete=models.CASCADE)
    idRes =   models.ForeignKey(Respondant, on_delete=models.CASCADE)
    pk =    models.CompositePrimaryKey('idS', 'idRes')

class SatisfationGrade(models.Model):
    RANKING_GLOBAL = []
    for i in range(1, 10):
        RANKING_GLOBAL.append((i, str(i)))

    grade = models.PositiveSmallIntegerField(choices=RANKING_GLOBAL)
    idA =   models.ForeignKey(ProfesionalArea, on_delete=models.CASCADE)
    idRes =   models.ForeignKey(Respondant, on_delete=models.CASCADE)
    pk =    models.CompositePrimaryKey('idA', 'idRes')
    
# ------------- ANSWER CLASS --------------
# The class name is in spanish cause django don't permit other
class Respuesta(models.Model):
    answer = models.ForeignKey(Option, on_delete=models.CASCADE, null=True)# models.CharField(max_length=25, editable=False, blank=False)
    time = models.TimeField(editable=False, blank=False)
    date = models.DateTimeField(auto_now_add=True)
    respondant = models.ForeignKey(Respondant, on_delete=models.CASCADE)
    question = models.ForeignKey(Question, on_delete=models.CASCADE)
    pk = models.CompositePrimaryKey('respondant','question')

    class Meta:
        ordering = ['-date']
    
    def __str__(self):
        return str('ID ' + self.pk + ' Enunciado ' + self.answer)

